import type { NextConfig } from 'next';

const nextConfig: NextConfig = {
  transpilePackages: [
    '@tpmjs/ui',
    '@tpmjs/utils',
    '@tpmjs/db',
    '@tpmjs/types',
    '@tpmjs/env',
    '@tpmjs/config',
    '@tpmjs/registry-search',
    '@tpmjs/registry-execute',
  ],
  reactStrictMode: true,
  serverExternalPackages: ['@tpmjs/package-executor'],
  async redirects() {
    return [
      {
        source: '/tools-ideas',
        destination: '/tool-ideas',
        permanent: true,
      },
    ];
  },
};

export default nextConfig;

'use client';

import { Button } from '@tpmjs/ui/Button/Button';
import { Container } from '@tpmjs/ui/Container/Container';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import Link from 'next/link';
import { useEffect } from 'react';

export default function ErrorPage({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}): React.ReactElement {
  useEffect(() => {
    // Log the error to an error reporting service
    console.error('Error boundary caught:', error);
  }, [error]);

  return (
    <main className="flex-1">
      <section className="py-24 bg-background min-h-screen flex items-center">
        <Container size="xl" padding="lg">
          <div className="max-w-2xl mx-auto text-center">
            {/* Error Icon */}
            <div className="mb-8">
              <div className="inline-flex items-center justify-center w-24 h-24 rounded-full bg-error/10 mb-4">
                <Icon icon="alertTriangle" className="w-12 h-12 text-error" />
              </div>
              <h1 className="text-4xl md:text-5xl font-bold text-foreground mb-2">
                Something went wrong
              </h1>
              {/* Decorative divider */}
              <div className="h-1 w-24 bg-error mx-auto" />
            </div>

            {/* Error Message */}
            <p className="text-lg text-foreground-secondary mb-8 max-w-md mx-auto">
              An unexpected error occurred. This has been logged and we&apos;ll look into it.
            </p>

            {/* Error Details (in development) */}
            {process.env.NODE_ENV === 'development' && (
              <div className="mb-8 p-4 bg-surface border border-border rounded-lg text-left max-w-lg mx-auto">
                <p className="text-xs font-mono text-foreground-tertiary mb-2">
                  Error Details (dev only):
                </p>
                <p className="text-sm font-mono text-error break-all">{error.message}</p>
                {error.digest && (
                  <p className="text-xs font-mono text-foreground-tertiary mt-2">
                    Digest: {error.digest}
                  </p>
                )}
              </div>
            )}

            {/* Action Buttons */}
            <div className="flex flex-col sm:flex-row gap-4 justify-center items-center">
              <Button size="lg" variant="default" onClick={reset}>
                Try Again
              </Button>
              <Link href="/">
                <Button size="lg" variant="outline">
                  Go Home
                </Button>
              </Link>
            </div>

            {/* Helpful Links */}
            <div className="mt-12 pt-8 border-t border-border">
              <p className="text-sm text-foreground-tertiary mb-4">
                Need help or want to report this issue?
              </p>
              <div className="flex flex-wrap gap-4 justify-center text-sm">
                <a
                  href="https://github.com/tpmjs/tpmjs/issues"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-brutalist-accent hover:text-brutalist-accent-hover transition-colors"
                >
                  Report Issue
                </a>
                <Link
                  href="/tool/tool-search"
                  className="text-brutalist-accent hover:text-brutalist-accent-hover transition-colors"
                >
                  Browse Tools
                </Link>
                <Link
                  href="/how-it-works"
                  className="text-brutalist-accent hover:text-brutalist-accent-hover transition-colors"
                >
                  How It Works
                </Link>
              </div>
            </div>
          </div>
        </Container>
      </section>
    </main>
  );
}

import { createEnv } from '@tpmjs/env';
import { z } from 'zod';

export const env = createEnv({
  NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),
  NEXT_PUBLIC_API_URL: z.string().url().optional(),
  CRON_SECRET: z.string().min(32).optional(), // Required for Vercel Cron security
  RAILWAY_EXECUTOR_URL: z
    .string()
    .url()
    .default('https://endearing-commitment-production.up.railway.app'), // Railway service for health checks

  // Better Auth
  BETTER_AUTH_SECRET: z.string().min(32).optional(), // Required for session encryption
  BETTER_AUTH_URL: z.string().url().optional(), // Base URL for auth callbacks

  // Resend (Email)
  RESEND_API_KEY: z.string().startsWith('re_').optional(), // Resend API key for sending emails

  // Discord Summary Agent
  DISCORD_SUMMARY_AGENT_ID: z.string().optional(), // Agent ID for Discord summary cron
  DISCORD_GUILD_ID: z.string().optional(), // Discord server ID to summarize
  DISCORD_SUMMARY_CHANNEL_ID: z.string().optional(), // Channel to post summaries to
});

